@push('scripts')<script>(()=>{let i=0;const host=document.getElementById('order-lines'),tpl=document.getElementById('order-line');function calc(){let total=0;host.querySelectorAll('.order-line').forEach(r=>total+=(+r.querySelector('.qty').value||0)*(+r.querySelector('.price').value||0));document.getElementById('order-total').textContent=total.toFixed(2)+' Rs'}function add(){const r=tpl.content.firstElementChild.cloneNode(true);r.innerHTML=r.innerHTML.replaceAll('ROW',i++);host.append(r);r.querySelector('.product').addEventListener('change',e=>{const o=e.target.selectedOptions[0];r.querySelector('.price').value=o.dataset.price||0;r.querySelector('.tax').value=o.dataset.tax||'';r.querySelector('.description').value=o.text;calc()});r.querySelector('.remove').onclick=()=>{r.remove();calc()};r.addEventListener('input',calc)}document.getElementById('add-order-line').onclick=add;add()})()</script>@endpush
